        // 阈值 0.4，分量 0.3/0.4 → 合成 0.5 超限：实际值 0.5000、要求值 0.4、差额 -0.1
        setThreshold("INS-1", "th-9", "0.4");
        mvc.perform(put("/api/measurements/{key}/components", "B-9")
