    @Test
    void releaseSnapshotFrozenAgainstLaterThresholdRevision() throws Exception {
        createCert("INS-1");
        setThreshold("INS-1", "th-1", "1");
        submit("U-3", "INS-1", "alice");
        setComponents("U-3", "c-3", 1,
